messages.content:
{
  "type": "object",
  "properties": {
    "role": {
      "const": "assistant"
    },
    "content": {
      "anyOf": [
        {
          "anyOf": [
            {
              "type": "string",
              "description": "Plain text content."
            },
            {
              "type": "array",
              "items": {
                "$ref": "RichContentPart",
                "description": "A rich content part."
              },
              "description": "An array of rich content parts."
            }
          ],
          "description": "Rich content."
        },
        {
          "type": "null"
        }
      ]
    },
    "name": {
      "anyOf": [
        {
          "type": "string",
          "description": "An optional name for the participant. Provides the model information to differentiate between participants of the same role."
        },
        {
          "type": "null"
        }
      ]
    },
    "refusal": {
      "anyOf": [
        {
          "type": "string",
          "description": "The refusal message by the assistant."
        },
        {
          "type": "null"
        }
      ]
    },
    "tool_calls": {
      "anyOf": [
        {
          "type": "array",
          "items": {
            "$ref": "AssistantMessageToolCall",
            "description": "A tool call made by the assistant."
          },
          "description": "Tool calls made by the assistant."
        },
        {
          "type": "null"
        }
      ]
    },
    "reasoning": {
      "anyOf": [
        {
          "type": "string",
          "description": "The reasoning provided by the assistant."
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "role"
  ],
  "description": "Messages sent by the model in response to user messages."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "input_audio"
    },
    "input_audio": {
      "type": "object",
      "properties": {
        "data": {
          "type": "string",
          "description": "Base64 encoded audio data."
        },
        "format": {
          "enum": [
            "wav",
            "mp3"
          ],
          "description": "The format of the encoded audio data."
        }
      },
      "required": [
        "data",
        "format"
      ],
      "description": "The audio data and its format."
    }
  },
  "required": [
    "type",
    "input_audio"
  ],
  "description": "An audio rich content part."
}
